<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{listarTareas,recibirTarea,type Option,type Tarea}from'../services/tareas'
const props=withDefaults(defineProps<{area?:string;areaNombre?:string;descripcion?:string}>(),{area:'catastro',areaNombre:'Catastro',descripcion:'Solicitudes y reclamos derivados a la sección de Catastro.'});const rows=ref<Tarea[]>([]),districts=ref<Option[]>([]),types=ref<Option[]>([]),total=ref(0),lastPage=ref(1),loading=ref(false),receiving=ref<number|null>(null),error=ref(''),success=ref('');const filters=reactive({criterio:'',distrito_id:0,tipo_atencion_id:0,page:1});async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarTareas(filters,props.area);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;districts.value=r.distritos;types.value=r.tipos_atencion}catch(e){error.value=msg(e)}finally{loading.value=false}}async function receive(x:Tarea){if(!confirm(`¿Recibir la tarea #${x.id} vinculada al ticket #${x.ticket_id}?`))return;receiving.value=x.id;try{await recibirTarea(x.id,props.area);rows.value=rows.value.filter(r=>r.id!==x.id);total.value--;success.value='Tarea recibida correctamente. Ahora se encuentra en tus tareas pendientes.'}catch(e){error.value=msg(e)}finally{receiving.value=null}}function clear(){Object.assign(filters,{criterio:'',distrito_id:0,tipo_atencion_id:0});load(1)}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Catastro / Tareas</nav><header class="hero"><div class="mark">TA</div><div><small>EVAN · CATASTRO COMERCIAL</small><h1>Tareas por recibir</h1><p>Solicitudes y reclamos derivados a la sección de Catastro.</p></div><div class="counter"><b>{{total}}</b><span>tareas disponibles</span></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Ticket o tarea<input v-model.trim="filters.criterio" placeholder="Número de ticket" @keyup.enter="load(1)"></label><label>Distrito<select v-model.number="filters.distrito_id"><option :value="0">Todos</option><option v-for="x in districts" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de atención<select v-model.number="filters.tipo_atencion_id"><option :value="0">Todos</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><div><button @click="load(1)">Consultar</button><button class="clear" @click="clear">Limpiar</button></div></section><div v-if="loading" class="empty">Cargando tareas de Catastro…</div><div v-else-if="!rows.length" class="empty"><b>Sin tareas disponibles</b><span>No existen solicitudes o reclamos pendientes de recepción.</span></div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><header><div><small>TAREA</small><b>#{{x.id}}</b></div><span>{{x.estado}}</span></header><h2>{{x.tipo_tarea}}</h2><p>{{x.descripcion||'Sin indicaciones adicionales.'}}</p><dl><div><dt>Ticket</dt><dd>#{{x.ticket_id}}</dd></div><div><dt>Tipo</dt><dd>{{x.tipo_atencion}}</dd></div><div><dt>Cliente</dt><dd>{{x.cliente}}</dd></div><div><dt>Distrito</dt><dd>{{x.distrito}}</dd></div><div class="wide"><dt>Dirección</dt><dd>{{x.direccion||'—'}}</dd></div><div><dt>Enviada por</dt><dd>{{x.usuario_envia}}</dd></div></dl><footer><small>{{x.fecha}}</small><button :disabled="receiving===x.id" @click="receive(x)">{{receiving===x.id?'Recibiendo…':'Recibir tarea'}}</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer></div></template>
<style scoped>
.page{--a:#566d7b;color:#37464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.cards small{color:var(--a);font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.counter{margin-left:auto;text-align:right}.counter b,.counter span{display:block}.counter b{font-size:.9rem}.counter span{font-size:.43rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1fr 1fr 1.3fr auto;align-items:end;gap:8px;background:#fff}.filters label{font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.filters button,.pages button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.47rem}.filters .clear{margin-left:4px;color:#68767c;background:#edf1f2}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.cards article{padding:13px;display:flex;flex-direction:column;border-top:4px solid var(--a);border-radius:8px;background:#fff}.cards article>header{display:flex;justify-content:space-between}.cards header b,.cards header small{display:block}.cards header span{padding:4px 7px;border-radius:9px;color:#566d7b;background:#edf2f4;font-size:.42rem}.cards h2{margin:10px 0 3px;font-size:.68rem}.cards>article>p{min-height:28px;margin:0;color:#78858b;font-size:.47rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:10px 0}.cards dt{color:#8c979c;font-size:.4rem}.cards dd{margin:1px 0;font-size:.48rem;font-weight:700}.cards .wide{grid-column:span 2}.cards article>footer{margin-top:auto;padding-top:9px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e8ecee}.cards footer small{color:#8c969a;font-size:.4rem}.cards footer button{padding:7px 10px;border:0;border-radius:4px;color:#fff;background:#288268;font-size:.46rem}.empty{margin-top:12px;padding:45px;display:grid;gap:5px;text-align:center;background:#fff;font-size:.58rem}.empty span{color:#8a959a}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}@media(max-width:850px){.cards{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.counter{margin-left:0}.cards,.filters{grid-template-columns:1fr}}
</style>
